pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    let mut score = 0.0;

    // Progress factor: heavier penalty early in the stream
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };
    let residual_weight = 1.0 + (1.0 - progress) * 0.5; // 1.5 early, 1.0 late

    // Base score: tighter fits are better
    score += (post_residual as f64) * residual_weight;

    // Lookahead: penalize bins that leave too much space for the next item
    if next_item_size > 0 {
        let diff = post_residual as i32 - next_item_size as i32;
        if diff < 0 {
            // Next item won't fit – huge penalty
            score += 2000.0;
        } else {
            // Small excess space is acceptable; larger excess is penalized
            score += (diff as f64) * 0.3;
        }
    }

    // Balance residuals: avoid leaving bins with residuals far from the mean
    let mean_diff = (post_residual as f64 - mean_residual).abs();
    score += mean_diff * 0.1;

    // Penalize having many open bins (encourages closing bins sooner)
    score += (open_bins_count as f64) * 0.4;

    // If this is the only bin that can fit the item, strongly reward it
    if fitting_bins_count == 1 {
        score -= 1500.0;
    }

    // New-bin candidate: discourage opening a new bin when open bins exist
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 50.0;
        }
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Normalized stream progress in [0,1)
    let progress = step_index as f64 / total_items as f64;
    // Residual after placing the item
    let pr = post_residual as f64;

    // Base score: the more space left, the higher the score
    let mut score = pr;

    // Polynomial coupling of residual with progress
    // Early in the stream we reward bins that leave less residual,
    // later we penalize large residuals
    score += pr.powi(2) * (progress - 0.5);

    // Prefer bins that are the only fit early in the stream
    score -= (fitting_bins_count as f64).powi(2) * (1.0 - progress);

    // Encourage using bins with higher mean residual later
    score += mean_residual * progress;

    // If many bins are open, slightly penalise keeping them open early
    score += (open_bins_count as f64) * (1.0 - progress) * 0.5;

    // Consider the next item if available
    if next_item_size > 0 {
        if next_item_size > post_residual {
            // Not enough space for the next item: penalise
            score += (next_item_size - post_residual) as f64 * (1.0 - progress) * 0.3;
        } else {
            // Plenty of space for the next item: reward
            score -= (post_residual - next_item_size) as f64 * progress * 0.3;
        }
    }

    // Ensure the score stays finite
    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score: leftover space after placing the item (higher is worse)
    let mut score = post_residual as f64;

    // Progress in the stream: 0.0 at start, 1.0 at end
    let progress = step_index as f64 / total_items as f64;

    // --- New bin handling ----------------------------------------------------
    // A brand‑new bin is marked by bin_residual == bin_capacity.
    // Penalise opening a new bin strongly at the start of the stream,
    // and gradually relax the penalty as we approach the end.
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress);
    } else {
        // Slight reward for re‑using an existing bin
        score -= progress * 1.0;
    }

    // --- Fitting bins count --------------------------------------------------
    // If this is the only open bin that can fit the item, we favour it.
    if fitting_bins_count == 1 {
        score -= 6.0;
    }

    // --- Lookahead penalty ---------------------------------------------------
    // Penalise bins that would leave insufficient space for the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.7;
    }

    // --- Mean residual coupling ---------------------------------------------
    // Encourage packing that keeps the residual close to the global mean.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.4;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.2;
    }

    // --- Open bins count penalty --------------------------------------------
    // Too many open bins indicate poor packing efficiency.
    if open_bins_count > 1 {
        score += (open_bins_count as f64 - 1.0) * 2.5;
    }

    // --- Large item tweak ----------------------------------------------------
    // For very large items (size > 70) avoid creating tiny residuals.
    if item_size > 70 {
        score += (100 - post_residual as i32) as f64 * 0.05;
    }

    // --- End‑of‑stream bonus -------------------------------------------------
    // Near the end, we reward very tight packing.
    if progress > 0.8 && post_residual < 10 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score is the residual left after placement
    let mut score = post_residual as f64;

    // Strongly prefer the sole fitting bin
    if fitting_bins_count == 1 {
        score -= 1000.0;
    }

    // Penalize dead space that cannot accommodate the next item
    if next_item_size > 0 && post_residual < next_item_size {
        let dead = next_item_size - post_residual;
        score += (dead as f64).powi(2) * 0.5; // quadratic penalty
    }

    // Extra penalty for very small gaps
    if post_residual < 5 {
        score += 20.0;
    }

    // Pressure to reduce the number of open bins
    score += open_bins_count as f64 * 1.5;

    // Avoid opening a new bin unless forced
    if bin_residual == bin_capacity {
        score += 50.0;
    }

    // Reward tight fits: lower residual after placement
    let used = bin_capacity - post_residual;
    score -= used as f64 * 0.1;

    // Penalize bins that are looser than the average residual
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.3;
    }

    // Reward placing large items (they help fill bins)
    if item_size > 60 {
        score -= 5.0;
    }

    // Encourage tighter packing later in the stream
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

