pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score starts with the residual space after placement
    let mut score = post_residual as f64;

    // Penalize bins that would become unusable for the next item
    if next_item_size > 0 && post_residual < next_item_size {
        score += 100.0 * (next_item_size - post_residual) as f64;
    }

    // Heavy penalty for very small gaps (dead space)
    if post_residual < 15 {
        score += 30.0;
    }

    // Pressure to close bins: more open bins → higher penalty
    score += (open_bins_count as f64) * 0.5;

    // If this is the last fitting bin, slightly favor using it
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New bin candidate: add a modest penalty to avoid opening unless necessary
    if bin_residual == bin_capacity {
        score += 20.0;
    }

    // Reward bins that are tighter than the average residual
    let mean_diff = mean_residual - post_residual as f64;
    if mean_diff > 0.0 {
        score -= mean_diff * 0.05;
    }

    // Optional: mild adjustment based on stream position (later stages favor tighter bins)
    let progress = (step_index as f64) / (total_items as f64);
    score += progress * 0.1 * (post_residual as f64);

    score
}
